import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { container } from "@/src/infrastructure/composition/root-container";
import { PageShell } from "@/src/presentation/components/layout/PageShell";

type PaginaProductoProps = {
  params: Promise<{ id: string }>;
};

async function obtenerProducto(id: string) {
  return container.products.getProductById(id);
}

export async function generateMetadata({
  params,
}: PaginaProductoProps): Promise<Metadata> {
  const { id } = await params;
  const producto = await obtenerProducto(id);

  if (!producto || producto.estado !== "activo") {
    return { title: "Producto no disponible | Marin Industries" };
  }

  const descripcion =
    producto.descripcion?.trim() ||
    `Consulta el precio y los detalles de ${producto.nombre} en Marin Industries.`;

  const imagen = producto.imagen;

  return {
    title: `${producto.nombre} | Marin Industries`,
    description: descripcion,
    openGraph: {
      title: producto.nombre,
      description: `${descripcion} Precio: $${producto.precio} MXN.`,
      type: "website",
      images: imagen ? [{ url: imagen, alt: producto.nombre }] : [],
    },
    twitter: {
      card: "summary_large_image",
      title: producto.nombre,
      description: descripcion,
      images: imagen ? [imagen] : [],
    },
  };
}

export default async function PaginaProducto({
  params,
}: PaginaProductoProps) {
  const { id } = await params;
  const producto = await obtenerProducto(id);

  if (!producto || producto.estado !== "activo") {
    notFound();
  }

  const precio = new Intl.NumberFormat("es-MX", {
    style: "currency",
    currency: "MXN",
  }).format(producto.precio);

  return (
    <PageShell>
      <main className="producto-publico">
        <div className="producto-publico__contenedor">
          <Link href="/tienda" className="producto-publico__volver">
            ← Ir a la tienda
          </Link>

          <article className="producto-publico__tarjeta">
            <div className="producto-publico__imagen">
              {producto.imagen ? (
                <img src={producto.imagen} alt={producto.nombre} />
              ) : (
                <span>Imagen no disponible</span>
              )}
            </div>

            <div className="producto-publico__contenido">
              <span className="eyebrow">
                MARIN INDUSTRIES / PRODUCTOS
              </span>

              <p className="producto-publico__categoria">
                {producto.categoria}
              </p>

              <h1>{producto.nombre}</h1>

              <p className="producto-publico__precio">{precio} MXN</p>

              <p className="producto-publico__descripcion">
                {producto.descripcion}
              </p>

              <Link
                href="/tienda"
                className="btn btn-primary"
              >
                Ir a la tienda
              </Link>

              <p className="producto-publico__nota">
                Ingeniería · Tecnología · Suministro
              </p>
            </div>
          </article>
        </div>
      </main>
    </PageShell>
  );
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import type { CaseStudy } from "@/src/domain/marketing/landing-content.entity";
import { useLanguage } from "../../i18n/LanguageProvider";

type CaseAccordionProps = {
  studies: CaseStudy[];
  visuals: ReactNode[];
};

const pad = (n: number) => String(n).padStart(2, "0");

export function CaseAccordion({ studies, visuals }: CaseAccordionProps) {
  const { translations } = useLanguage();
  const copy = translations.home.caseStudies;
  const [active, setActive] = useState(0);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const last = studies.length - 1;

  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current);
    },
    []
  );

  // Abrir al pasar el mouse (solo desktop con mouse), con pequeña pausa
  const hoverOpen = (i: number) => {
    if (!window.matchMedia("(hover: hover) and (min-width: 901px)").matches) return;
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => setActive(i), 110);
  };

  const cancelHover = () => {
    if (timer.current) clearTimeout(timer.current);
  };

  const next = (i: number) => {
    if (i < last) {
      setActive(i + 1);
    } else {
      document
        .getElementById("contacto")
        ?.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  return (
    <div
      className="ca-track"
      onMouseLeave={cancelHover}
      onKeyDown={(e) => {
        if (e.key === "ArrowRight") setActive((a) => Math.min(last, a + 1));
        if (e.key === "ArrowLeft") setActive((a) => Math.max(0, a - 1));
      }}
    >
      {studies.map((s, i) => {
        const isActive = i === active;
        const translated = copy.items[s.id as keyof typeof copy.items];
        const title = translated?.title ?? s.title;
        const type = translated?.type ?? s.type;
        const sector = translated?.sector ?? s.sector;
        const description = translated?.copy ?? s.copy;
        const benefits = translated?.benefits ?? s.benefits;

        return (
          <article
            key={s.id}
            className="ca-panel"
            data-active={isActive}
            data-next={i === active + 1}
            onMouseEnter={() => hoverOpen(i)}
          >
            {/* Estado cerrado */}
            <button
              type="button"
              className="ca-collapsed"
              aria-expanded={isActive}
              aria-label={`${copy.openCase}: ${s.tag}, ${type}`}
              tabIndex={isActive ? -1 : 0}
              onClick={() => setActive(i)}
            >
              <span className="ca-num">{pad(i + 1)}</span>
              <span className="ca-vtag">
                {s.tag}
                <small>{s.type}</small>
              </span>
              <span className="ca-plus" aria-hidden="true">
                +
              </span>
            </button>

            {/* Estado abierto */}
            <div className="ca-open" inert={!isActive}>
              <div className="ca-open-inner">
                <div className="ca-visual">{s.img?.[0] ? <img src={s.img[0]} alt={title} /> : visuals[i]}</div>

                <div className="ca-info">
                  <div className="ca-meta">
                    <span className="ca-badge">{s.tag}</span>
                    <span>
                      {type} · {sector}
                    </span>
                  </div>

                  <h3 className="ca-h3">{title}</h3>
                  <p className="ca-copy">{description}</p>

                  <ul className="ca-benefits">
                    {benefits.map((b) => (
                      <li key={b}>
                        <svg
                          viewBox="0 0 24 24"
                          fill="none"
                          stroke="currentColor"
                          strokeWidth="2.2"
                          aria-hidden="true"
                        >
                          <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                        </svg>
                        {b}
                      </li>
                    ))}
                  </ul>

                  <div className="ca-foot">
                    <button
                      type="button"
                      className="btn btn-primary ca-next"
                      onClick={() => next(i)}
                    >
                      {i < last ? copy.next : copy.contact}
                      <span aria-hidden="true">{i < last ? "→" : "↓"}</span>
                    </button>
                    <span className="ca-count">
                      {pad(i + 1)} / {pad(studies.length)}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </article>
        );
      })}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useLanguage } from "../../i18n/LanguageProvider";

const SECTION_IDS = ["inicio", "empresa", "casos", "contacto"] as const;

export function SectionRail() {
  const { translations } = useLanguage();
  const labels = translations.home.sectionRail.sections;
  const sections = SECTION_IDS.map((id) => ({ id, label: labels[id as keyof typeof labels] }));
  const [active, setActive] = useState(0);
  const [open, setOpen] = useState(false);
  const boxRef = useRef<HTMLDivElement>(null);

  // Scroll-spy: la sección activa es la última cuyo borde superior ya pasó el 40% de la pantalla
  useEffect(() => {
    let raf = 0;

    const update = () => {
      raf = 0;
      const line = window.innerHeight * 0.4;
      let current = 0;

      sections.forEach((s, i) => {
        const el = document.getElementById(s.id);
        if (el && el.getBoundingClientRect().top <= line) current = i;
      });

      setActive(current);
    };

    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(update);
    };

    update();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);

    return () => {
      if (raf) cancelAnimationFrame(raf);
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
    };
  }, []);

  // Menú móvil: cerrar con Escape o al tocar fuera
  useEffect(() => {
    if (!open) return;

    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    const onDown = (e: PointerEvent) => {
      if (!boxRef.current?.contains(e.target as Node)) setOpen(false);
    };

    window.addEventListener("keydown", onKey);
    window.addEventListener("pointerdown", onDown);

    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("pointerdown", onDown);
    };
  }, [open]);

  const goTo = (id: string) => {
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    document
      .getElementById(id)
      ?.scrollIntoView({ behavior: reduce ? "auto" : "smooth", block: "start" });
    setOpen(false);
  };

  const pad = (n: number) => String(n).padStart(2, "0");

  return (
    <div ref={boxRef}>
      {/* Desktop: riel de marcas */}
      <nav className="rail" aria-label={translations.home.sectionRail.ariaLabel}>
        {sections.map((s, i) => (
          <button
            key={s.id}
            type="button"
            className="rail-item"
            data-active={i === active}
            aria-label={s.label}
            aria-current={i === active ? "true" : undefined}
            onClick={() => goTo(s.id)}
          >
            <span className="rail-label">{s.label}</span>
            <span className="rail-tick" />
          </button>
        ))}
      </nav>

      {/* Celular: botón índice */}
      <div className="rail-m">
        <button
          type="button"
          className="rail-m-btn"
          aria-expanded={open}
          aria-label={translations.home.sectionRail.mobileLabel}
          onClick={() => setOpen((o) => !o)}
        >
          {pad(active + 1)}
          <span>/{pad(sections.length)}</span>
        </button>

        <div className="rail-m-menu" data-open={open} inert={!open}>
          {sections.map((s, i) => (
            <button
              key={s.id}
              type="button"
              className="rail-m-item"
              data-active={i === active}
              onClick={() => goTo(s.id)}
            >
              <small>{pad(i + 1)}</small>
              {s.label}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useState } from "react";
import { ThemeToggle } from "./ThemeToggle";
import { useLanguage } from "../../i18n/LanguageProvider";

const navItems = [
  { label: "announcements", href: "/convocatorias" },
  { label: "services", href: "/servicios" },
  { label: "quotation", href: "/cotizacion" },
  { label: "humanResources", href: "/rh" },
  { label: "products", href: "/tienda" },
] as const;

export function Header() {
  const pathname = usePathname();
  const [open, setOpen] = useState(false);
  const { language, setLanguage, translations } = useLanguage();

  const isActive = (href: string) =>
    pathname === href || pathname.startsWith(`${href}/`);

  return (
    <header className="fixed left-0 top-0 z-50 w-full border-b border-brandLine bg-brandBg">
      <div className="section-shell flex items-center justify-between py-4">
        <Link href="/" className="flex items-center gap-4">
          <div className="h-10 w-10 overflow-hidden">
            <img
              src="/assets/logo.png"
              alt="Marin Industries Logo"
              className="h-full w-full object-cover"
            />
          </div>

          <span className="text-sm font-semibold tracking-tight text-brandDark">
            MARIN INDUSTRIES
          </span>
        </Link>

        <div className="flex items-center gap-4 lg:gap-6">
          <nav className="hidden items-center gap-8 text-sm font-medium lg:flex">
            {navItems.map((item) => {
              const esTienda = item.label === "products";

              return (
                <Link
                  key={item.href}
                  href={item.href}
                  target={esTienda ? "_blank" : undefined}
                  rel={esTienda ? "noopener noreferrer" : undefined}
                  aria-current={isActive(item.href) ? "page" : undefined}
                  className={`transition hover:text-brandAccent ${
                    isActive(item.href) ? "text-brandAccent" : "text-brandText"
                  }`}
                >
                  {translations.header.navigation[item.label]}
                </Link>
              );
            })}
          </nav>

          <ThemeToggle />
          <div
            className="flex items-center gap-1 rounded-md border border-brandLine p-1"
            aria-label={translations.language.select}
          >
            <button
              type="button"
              onClick={() => setLanguage("es")}
              aria-pressed={language === "es"}
              className={`rounded px-2 py-1 text-xs font-semibold transition ${
                language === "es"
                  ? "bg-brandAccent text-brandDark"
                  : "text-brandText hover:text-brandAccent"
              }`}
            >
              ES
            </button>

            <button
              type="button"
              onClick={() => setLanguage("en")}
              aria-pressed={language === "en"}
              className={`rounded px-2 py-1 text-xs font-semibold transition ${
                language === "en"
                  ? "bg-brandAccent text-brandDark"
                  : "text-brandText hover:text-brandAccent"
              }`}
            >
              EN
            </button>
          </div>

          <button
            type="button"
            className="lg:hidden"
            onClick={() => setOpen((prev) => !prev)}
            aria-label={
              open
                ? translations.header.closeMenu
                : translations.header.openMenu
            }
            aria-expanded={open}
          >
            <span className="block h-0.5 w-7 bg-brandDark" />
            <span className="mt-1.5 block h-0.5 w-7 bg-brandDark" />
            <span className="mt-1.5 block h-0.5 w-7 bg-brandDark" />
          </button>
        </div>
      </div>

      {open ? (
        <div className="border-t border-brandLine bg-brandBg px-6 py-4 lg:hidden">
          <nav className="flex flex-col gap-4 text-sm font-medium">
            {navItems.map((item) => (
              <Link
                key={item.href}
                href={item.href}
                onClick={() => setOpen(false)}
                className={`transition hover:text-brandAccent ${
                  isActive(item.href) ? "text-brandAccent" : "text-brandText"
                }`}
              >
                {translations.header.navigation[item.label]}
              </Link>
            ))}
          </nav>
        </div>
      ) : null}
    </header>
  );
}

"use client";

import type { Producto } from "./TarjetaProducto";
import { useLanguage } from "../../i18n/LanguageProvider";

type CarritoItemProps = {
  producto: Producto;
  cantidad: number;
  onCambiarCantidad: (cantidad: number) => void;
  onEliminar: () => void;
};

const moneda = (precio: number) =>
  new Intl.NumberFormat("es-MX", {
    style: "currency",
    currency: "MXN",
  }).format(precio);

export function CarritoItem({
  producto,
  cantidad,
  onCambiarCantidad,
  onEliminar,
}: CarritoItemProps) {
  const { translations } = useLanguage();
  const t = translations.store;
  return (
    <article className="carrito-item">
      <img className="carrito-item-imagen" src={producto.imagen} alt="" />
      <div className="carrito-item-info">
        <span className="producto-categoria">{producto.categoria}</span>
        <h3>{producto.nombre}</h3>
        <p>{moneda(producto.precio)} {t.perUnit}</p>
        <div className="carrito-item-controles">
          <div className="carrito-cantidad-control" aria-label={`${t.quantity} de ${producto.nombre}`}>
            <button
              type="button"
              aria-label={`${t.reduce} de ${producto.nombre}`}
              onClick={() => onCambiarCantidad(cantidad - 1)}
            >
              −
            </button>
            <span aria-live="polite">{cantidad}</span>
            <button
              type="button"
              aria-label={`${t.increase} de ${producto.nombre}`}
              disabled={cantidad >= producto.existencia}
              onClick={() => onCambiarCantidad(cantidad + 1)}
            >
              +
            </button>
          </div>
          <button
            type="button"
            className="carrito-item-eliminar"
            onClick={onEliminar}
          >
            {t.remove}
          </button>
        </div>
      </div>
      <strong className="carrito-item-total">
        {moneda(producto.precio * cantidad)}
      </strong>
    </article>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { TarjetaProducto, type Producto } from "./TarjetaProducto";
import { CarritoItem } from "./CarritoItem";

import { CompartirProductoModal } from "./CompartirProductoModal";

const CARRITO_STORAGE_KEY = STORE_CART_KEY;



import { container } from "@/src/infrastructure/composition/root-container";
import { productosEstaticos } from "@/src/infrastructure/products/static-product.repository";

import { useRouter } from "next/navigation";
import { saveStoreCheckout, STORE_CART_KEY } from "@/src/infrastructure/sales/store-checkout.storage";
import { computeStoreTotals } from "@/src/domain/store/store-pricing";
import { useLanguage } from "../../i18n/LanguageProvider";

const moneda = (precio: number) =>
  new Intl.NumberFormat("es-MX", {
    style: "currency",
    currency: "MXN",
  }).format(precio);

type GridProductosProps = {
  productosInicialesProp?: Producto[];
};

export function GridProductos({
  productosInicialesProp,
}: GridProductosProps = {}) {
  const { translations } = useLanguage();
  const t = translations.store;
  const [productos, setProductos] = useState<Producto[]>(
    productosInicialesProp && productosInicialesProp.length > 0
      ? productosInicialesProp
      : productosEstaticos,
  );

  const [cargando, setCargando] = useState(false);
  const [busqueda, setBusqueda] = useState("");
  const [categoria, setCategoria] = useState("Todas");
  const [soloOfertas, setSoloOfertas] = useState(false);
  const [productoExpandido, setProductoExpandido] = useState<string | null>(
    null,
  );
  const [carrito, setCarrito] = useState<Record<string, number>>({});
  const [carritoAbierto, setCarritoAbierto] = useState(false);
  const [carritoCargado, setCarritoCargado] = useState(false);
  const router = useRouter();

  const [productoParaCompartir, setProductoParaCompartir] =
  useState<Producto | null>(null);

  // Cargar productos desde la base de datos (Supabase o respaldo estático)
  useEffect(() => {
    let activo = true;
    setCargando(true);
    container.products
      .listProducts({ soloActivos: true })
      .then((items) => {
        if (activo && items.length > 0) {
          setProductos(items);
        }
      })
      .catch((err) => {
        console.warn(
          "No se pudieron cargar productos de la base de datos:",
          err,
        );
      })
      .finally(() => {
        if (activo) setCargando(false);
      });

    return () => {
      activo = false;
    };
  }, []);

  useEffect(() => {
    try {
      const guardado = window.localStorage.getItem(CARRITO_STORAGE_KEY);
      if (guardado) {
        const cantidades = JSON.parse(guardado) as Record<string, number>;
        setCarrito(
          Object.fromEntries(
            Object.entries(cantidades).filter(
              ([id, cantidad]) =>
                productos.some((producto) => producto.id === id) &&
                Number.isInteger(cantidad) &&
                cantidad > 0,
            ),
          ),
        );
      }
    } catch {
      window.localStorage.removeItem(CARRITO_STORAGE_KEY);
    }
    setCarritoCargado(true);
  }, [productos]);

  useEffect(() => {
    if (!carritoCargado) return;

    try {
      window.localStorage.setItem(CARRITO_STORAGE_KEY, JSON.stringify(carrito));
    } catch {}
  }, [carrito, carritoCargado]);

  useEffect(() => {
    const cerrarConEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setProductoExpandido(null);
        setCarritoAbierto(false);
      }
    };

    window.addEventListener("keydown", cerrarConEscape);
    return () => window.removeEventListener("keydown", cerrarConEscape);
  }, []);

  const categorias = useMemo(
    () => [
      "Todas",
      ...new Set(productos.map((producto) => producto.categoria)),
    ],
    [productos],
  );

  const productosFiltrados = useMemo(() => {
    const termino = busqueda.trim().toLowerCase();

    return productos.filter((producto) => {
      const coincideTexto =
        producto.nombre.toLowerCase().includes(termino) ||
        producto.descripcion.toLowerCase().includes(termino);

      const coincideCategoria =
        categoria === "Todas" || producto.categoria === categoria;

      const coincideOferta = !soloOfertas || producto.oferta === true;

      return coincideTexto && coincideCategoria && coincideOferta;
    });
  }, [productos, busqueda, categoria, soloOfertas]);

  const totalArticulos = Object.values(carrito).reduce(
    (total, cantidad) => total + cantidad,
    0,
  );
  const articulosCarrito = productos.flatMap((producto) => {
    const cantidad = carrito[producto.id] ?? 0;
    return cantidad > 0 ? [{ producto, cantidad }] : [];
  });
  // Mismo cálculo que el checkout y el servidor (el envío se suma en el checkout).
  const { subtotal, iva, total } = computeStoreTotals(
    articulosCarrito.map(({ producto, cantidad }) => ({ precio: producto.precio, cantidad })),
    { includeShipping: false },
  );

  const agregarAlCarrito = (producto: Producto) => {
    setCarrito((actual) => {
      const cantidadActual = actual[producto.id] ?? 0;

      if (cantidadActual >= producto.existencia) {
        return actual;
      }

      return {
        ...actual,
        [producto.id]: cantidadActual + 1,
      };
    });
  };

  const actualizarCantidad = (producto: Producto, cantidad: number) => {
    setCarrito((actual) => {
      const siguiente = { ...actual };
      if (cantidad <= 0) {
        delete siguiente[producto.id];
      } else {
        siguiente[producto.id] = Math.min(cantidad, producto.existencia);
      }
      return siguiente;
    });
  };

  const productoSeleccionado = productos.find(
    (producto) => producto.id === productoExpandido,
  );

  return (
    <section className="tienda-section">
      <div className="section-shell">
        <header className="tienda-encabezado">
          <div>
            <span className="eyebrow">MARIN INDUSTRIES / {t.catalog.toUpperCase()}</span>
            <h1 className="tienda-titulo">{t.catalog}</h1>
            <p className="tienda-descripcion">
              {t.description}
            </p>
          </div>

          <button
            type="button"
            className="btn btn-primary tienda-carrito"
            onClick={() => setCarritoAbierto(true)}
            aria-label={`${t.viewCart}, ${totalArticulos} ${t.articles}`}
          >
            {t.cart}{" "}
            <span className="tienda-carrito-cantidad">{totalArticulos}</span>
          </button>
        </header>

        <div className="tienda-controles">
          <label className="tienda-busqueda">
            <span>{t.search}</span>
            <input
              type="search"
              value={busqueda}
              onChange={(event) => setBusqueda(event.target.value)}
              placeholder={t.searchPlaceholder}
            />
          </label>

          <label className="tienda-categoria">
            <span>{t.category}</span>
            <select
              value={categoria}
              onChange={(event) => setCategoria(event.target.value)}
            >
              {categorias.map((nombre) => (
                <option key={nombre} value={nombre}>
                  {nombre}
                </option>
              ))}
            </select>
          </label>

          <button
            type="button"
            className={`btn ${soloOfertas ? "btn-primary" : "btn-ghost"}`}
            aria-pressed={soloOfertas}
            onClick={() => setSoloOfertas((actual) => !actual)}
          >
            {soloOfertas ? t.showAll : t.offers}
          </button>
        </div>

        {productosFiltrados.length > 0 ? (
          <div className="productos-grid">
            {productosFiltrados.map((producto) => (
              <TarjetaProducto
                key={producto.id}
                producto={producto}
                onExpandir={() => setProductoExpandido(producto.id)}
                onAgregarCarrito={agregarAlCarrito}
                onVerCarrito={() => setCarritoAbierto(true)}
                onCompartir={setProductoParaCompartir}
              />
            ))}
          </div>
        ) : (
          <p className="tienda-vacio">
            {t.emptyResults}
          </p>
        )}

        <footer className="tienda-pie">
          <span>{productosFiltrados.length} {t.productsFound}</span>
          <Link href="/cotizacion">{t.requestQuote}</Link>
        </footer>
      </div>

      {productoSeleccionado && (
        <div
          className="tienda-overlay"
          onClick={() => setProductoExpandido(null)}
        >
          <section
            className="producto-dialogo"
            role="dialog"
            aria-modal="true"
            aria-label={`${t.details} ${productoSeleccionado.nombre}`}
            onClick={(event) => event.stopPropagation()}
          >
            <button
              type="button"
              className="tienda-modal-cerrar"
              aria-label={t.closeDetails}
              onClick={() => setProductoExpandido(null)}
            >
              ×
            </button>
            <TarjetaProducto
              producto={productoSeleccionado}
              expandida
              onExpandir={() => {}}
              onAgregarCarrito={agregarAlCarrito}
              onCerrar={() => setProductoExpandido(null)}
              onVerCarrito={() => {
                setProductoExpandido(null);
                setCarritoAbierto(true);
              }}
              onCompartir={setProductoParaCompartir}
            />
          </section>
        </div>
      )}

      {productoParaCompartir && (
        <CompartirProductoModal
          producto={productoParaCompartir}
          onCerrar={() => setProductoParaCompartir(null)}
        />
      )}

      {carritoAbierto && (
        <div
          className="tienda-overlay"
          onClick={() => setCarritoAbierto(false)}
        >
          <section
            className="carrito-dialogo"
            role="dialog"
            aria-modal="true"
            aria-labelledby="carrito-titulo"
            onClick={(event) => event.stopPropagation()}
          >
            <header className="carrito-encabezado">
              <div>
                <span className="eyebrow">{t.order}</span>
                <h2 id="carrito-titulo">{t.cart}</h2>
                <p>{totalArticulos} {t.articles}</p>
              </div>
              <button
                type="button"
                className="tienda-modal-cerrar"
                aria-label={t.closeCart}
                onClick={() => setCarritoAbierto(false)}
              >
                ×
              </button>
            </header>

            {articulosCarrito.length > 0 ? (
              <div className="carrito-cuerpo">
                <div
                  className="carrito-articulos"
                  aria-label={t.cartItems}
                >
                  {articulosCarrito.map(({ producto, cantidad }) => (
                    <CarritoItem
                      key={producto.id}
                      producto={producto}
                      cantidad={cantidad}
                      onCambiarCantidad={(nuevaCantidad) =>
                        actualizarCantidad(producto, nuevaCantidad)
                      }
                      onEliminar={() => actualizarCantidad(producto, 0)}
                    />
                  ))}
                </div>

                <aside
                  className="carrito-resumen"
                  aria-label={t.priceSummary}
                >
                  <h3>{t.summary}</h3>
                  <dl>
                    <div>
                      <dt>{t.subtotal}</dt>
                      <dd>{moneda(subtotal)}</dd>
                    </div>
                    <div>
                      <dt>{t.tax}</dt>
                      <dd>{moneda(iva)}</dd>
                    </div>
                    <div className="carrito-total">
                      <dt>{t.total}</dt>
                      <dd>{moneda(total)}</dd>
                    </div>
                  </dl>
                  <button
                    type="button"
                    className="btn btn-ghost carrito-vaciar"
                    onClick={() => setCarrito({})}
                  >
                    {t.clear}
                  </button>
                  <button
                    type="button"
                    className="btn btn-primary carrito-continuar"
                    disabled={articulosCarrito.length === 0}
                    onClick={() => {
                      if (articulosCarrito.length === 0) return;

                      saveStoreCheckout({
                        items: articulosCarrito.map(
                          ({ producto, cantidad }) => ({
                            id: producto.id,
                            nombre: producto.nombre,
                            precio: producto.precio,
                            cantidad,
                          }),
                        ),
                        subtotal,
                        iva,
                        total,
                      });

                      setCarritoAbierto(false);
                      router.push("/tienda/pago");
                    }}
                  >
                    {t.checkout}
                  </button>
                  <button
                    type="button"
                    className="btn btn-primary carrito-continuar"
                    onClick={() => setCarritoAbierto(false)}
                  >
                    {t.continue}
                  </button>
                </aside>
              </div>
            ) : (
              <div className="carrito-vacio">
                <p>{t.emptyCart}</p>
                <button
                  type="button"
                  className="btn btn-primary"
                  onClick={() => setCarritoAbierto(false)}
                >
                  {t.explore}
                </button>
              </div>
            )}
          </section>
        </div>
      )}
    </section>
  );
}

